// Smoothly move the camera to a new position/reference over 40 frames
local hCam = CMND_GET_ACT_CAMERA();
CamCtrlMoveTo(hCam, 40, [122.3, 29.9, 64.6, -19.0, 17.3, -35.7]);
while (IsCamCtrlMove())
{
	suspend();
}

// Queue a camera move without applying it right away, by passing a negative move type
local hCam = CMND_GET_ACT_CAMERA();
CamCtrlMoveTo(hCam, 40, [122.3, 29.9, 64.6, -19.0, 17.3, -35.7], -1);
